import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans3d_kernel(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 Din,
    .param .u32 Hin,
    .param .u32 Win,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 KD,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_d,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_d,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_d,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups
)
{
  .reg .pred  %p<32>;
    .reg .b32   %r<200>;
    .reg .b64   %rd<100>;
    .reg .f32   %f<20>;

    // Load parameters
    ld.param.u64  %rd10, [in_ptr];
    ld.param.u64  %rd11, [w_ptr];
    ld.param.u64  %rd12, [b_ptr];
    ld.param.u64  %rd13, [out_ptr];

    ld.param.u32  %r10, [N];
    ld.param.u32  %r11, [Cin];
    ld.param.u32  %r12, [Cout];
    ld.param.u32  %r13, [Din];
    ld.param.u32  %r14, [Hin];
    ld.param.u32  %r15, [Win];
    ld.param.u32  %r16, [Dout];
    ld.param.u32  %r17, [Hout];
    ld.param.u32  %r18, [Wout];
    ld.param.u32  %r19, [KD];
    ld.param.u32  %r20, [KH];
    ld.param.u32  %r21, [KW];
    ld.param.u32  %r22, [stride_d];
    ld.param.u32  %r23, [stride_h];
    ld.param.u32  %r24, [stride_w];
    ld.param.u32  %r25, [pad_d];
    ld.param.u32  %r26, [pad_h];
    ld.param.u32  %r27, [pad_w];
    ld.param.u32  %r28, [dil_d];
    ld.param.u32  %r29, [dil_h];
    ld.param.u32  %r30, [dil_w];
    ld.param.u32  %r31, [groups];

    // thread/block indices
    mov.u32       %r40, %tid.x;
    mov.u32       %r41, %tid.y;
    mov.u32       %r42, %tid.z;
    mov.u32       %r43, %ctaid.x;
    mov.u32       %r44, %ctaid.y;
    mov.u32       %r45, %ctaid.z;
    mov.u32       %r46, %ntid.x;
    mov.u32       %r47, %ntid.y;
    mov.u32       %r48, %ntid.z;

    // ow = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32    %r50, %r43, %r46;
    add.u32       %r50, %r50, %r40;       // ow

    // oh = blockIdx.y * blockDim.y + threadIdx.y
    mul.lo.u32    %r51, %r44, %r47;
    add.u32       %r51, %r51, %r41;       // oh

    // Decode blockIdx.z into (b, oc, od)
    // tmp = blockIdx.z
    mov.u32       %r52, %r45;             // tmp
    // od = tmp % Dout
    rem.u32       %r53, %r52, %r16;       // od
    // tmp = tmp / Dout
    div.u32       %r52, %r52, %r16;
    // oc = tmp % Cout
    rem.u32       %r54, %r52, %r12;       // oc
    // b = tmp / Cout
    div.u32       %r55, %r52, %r12;       // b

    // Bounds checks for b, ow, oh, od
    setp.ge.u32   %p1, %r50, %r18;  // ow >= Wout
    setp.ge.u32   %p2, %r51, %r17;  // oh >= Hout
    or.pred       %p3, %p1, %p2;
    setp.ge.u32   %p4, %r53, %r16;  // od >= Dout
    or.pred       %p5, %p3, %p4;
    setp.ge.u32   %p6, %r55, %r10;  // b >= N
    or.pred       %p7, %p5, %p6;
    @%p7 bra      RET;

    // Prepare group-related values
    // Cout_per_group = Cout / groups
    div.u32       %r60, %r12, %r31;
    // Cin_per_group = Cin / groups
    div.u32       %r61, %r11, %r31;
    // g = oc / Cout_per_group
    div.u32       %r62, %r54, %r60;           // group index
    // oc_in_group = oc - g * Cout_per_group
    mul.lo.u32    %r63, %r62, %r60;
    sub.u32       %r64, %r54, %r63;           // oc_in_group
    // ic_start = g * Cin_per_group
    mul.lo.u32    %r65, %r62, %r61;           // ic_start
    // ic_end = ic_start + Cin_per_group
    add.u32       %r66, %r65, %r61;           // ic_end (exclusive)

    // Load bias if present
    mov.f32       %f0, 0f00000000;            // acc init 0.0
    setp.eq.u64   %p8, %rd12, 0;
    @%p8 bra      NO_BIAS_LOAD;
    {
        // addr_bias = b_ptr + oc * 4
        cvt.u64.u32  %rd20, %r54;
        mul.wide.u32 %rd21, %r54, 4;
        add.s64      %rd22, %rd12, %rd21;
        ld.global.f32 %f0, [%rd22];
    }
NO_BIAS_LOAD:

    // Convert some to signed for arithmetic with pads/dils
    // sd = (int)stride_d, sh = (int)stride_h, sw = (int)stride_w
    mov.u32       %r70, %r22;
    mov.u32       %r71, %r23;
    mov.u32       %r72, %r24;
    mov.u32       %r73, %r25;
    mov.u32       %r74, %r26;
    mov.u32       %r75, %r27;
    mov.u32       %r76, %r28;
    mov.u32       %r77, %r29;
    mov.u32       %r78, %r30;

    // Cast coordinates to signed
    mov.u32       %r79, %r53;  // od
    mov.u32       %r80, %r51;  // oh
    mov.u32       %r81, %r50;  // ow

    // KD loop
    mov.u32       %r90, 0;     // kd = 0
KD_LOOP:
    setp.ge.u32   %p10, %r90, %r19;
    @%p10 bra     KD_END;

    // t_d = od + pad_d - kd * dil_d
    mul.lo.u32    %r91, %r90, %r76;      // kd * dil_d
    add.u32       %r92, %r79, %r73;      // od + pad_d
    sub.s32       %r93, %r92, %r91;      // t_d
    // if (t_d % stride_d != 0) skip
    rem.s32       %r94, %r93, %r70;
    setp.ne.s32   %p11, %r94, 0;
    @%p11 bra     KD_CONT;

    // id = t_d / stride_d
    div.s32       %r95, %r93, %r70;      // id
    // bounds check 0 <= id < Din
    setp.lt.s32   %p12, %r95, 0;
    setp.ge.s32   %p13, %r95, %r13;
    or.pred       %p14, %p12, %p13;
    @%p14 bra     KD_CONT;

    // KH loop
    mov.u32       %r96, 0;               // kh = 0
KH_LOOP:
    setp.ge.u32   %p15, %r96, %r20;
    @%p15 bra     KH_END;

    // t_h = oh + pad_h - kh * dil_h
    mul.lo.u32    %r97, %r96, %r77;
    add.u32       %r98, %r80, %r74;
    sub.s32       %r99, %r98, %r97;      // t_h
    // if (t_h % stride_h != 0) skip
    rem.s32       %r100, %r99, %r71;
    setp.ne.s32   %p16, %r100, 0;
    @%p16 bra     KH_CONT;

    // ih = t_h / stride_h
    div.s32       %r101, %r99, %r71;     // ih
    // bounds check 0 <= ih < Hin
    setp.lt.s32   %p17, %r101, 0;
    setp.ge.s32   %p18, %r101, %r14;
    or.pred       %p19, %p17, %p18;
    @%p19 bra     KH_CONT;

    // KW loop
    mov.u32       %r102, 0;              // kw = 0
KW_LOOP:
    setp.ge.u32   %p20, %r102, %r21;
    @%p20 bra     KW_END;

    // t_w = ow + pad_w - kw * dil_w
    mul.lo.u32    %r103, %r102, %r78;
    add.u32       %r104, %r81, %r75;
    sub.s32       %r105, %r104, %r103;   // t_w
    // if (t_w % stride_w != 0) skip
    rem.s32       %r106, %r105, %r72;
    setp.ne.s32   %p21, %r106, 0;
    @%p21 bra     KW_CONT;

    // iw = t_w / stride_w
    div.s32       %r107, %r105, %r72;    // iw
    // bounds check 0 <= iw < Win
    setp.lt.s32   %p22, %r107, 0;
    setp.ge.s32   %p23, %r107, %r15;
    or.pred       %p24, %p22, %p23;
    @%p24 bra     KW_CONT;

    // ic loop: ic from ic_start to ic_end-1
    mov.u32       %r110, %r65;           // ic = ic_start
IC_LOOP:
    setp.ge.u32   %p25, %r110, %r66;
    @%p25 bra     IC_END;

    // Compute input offset:
    // idx_in = (((((b*Cin + ic)*Din + id)*Hin + ih)*Win + iw))
    // Use 64-bit accumulation
    mul.wide.u32   %rd31, %r55, %r11;           // b*Cin
    cvt.u64.u32    %rd70, %r110;                // ic
    add.s64        %rd31, %rd31, %rd70;
    cvt.u64.u32    %rd71, %r13;                 // Din
    mul.lo.u64     %rd31, %rd31, %rd71;
    cvt.u64.u32    %rd72, %r95;                 // id
    add.s64        %rd31, %rd31, %rd72;
    cvt.u64.u32    %rd73, %r14;                 // Hin
    mul.lo.u64     %rd31, %rd31, %rd73;
    cvt.u64.u32    %rd74, %r101;                // ih
    add.s64        %rd31, %rd31, %rd74;
    cvt.u64.u32    %rd75, %r15;                 // Win
    mul.lo.u64     %rd31, %rd31, %rd75;
    cvt.u64.u32    %rd76, %r107;                // iw
    add.s64        %rd31, %rd31, %rd76;
    shl.b64        %rd32, %rd31, 2;             // * sizeof(float)
    add.s64        %rd33, %rd10, %rd32;         // in_ptr + offset
    // Compute weight offset:
    // idx_w = (((((ic)*Cout_g + oc_in_group)*KD + kd)*KH + kh)*KW + kw)
    mul.wide.u32   %rd40, %r110, %r60;       // ic * Cout_g
    cvt.u64.u32    %rd80, %r64;              // oc_in_group
    add.s64        %rd40, %rd40, %rd80;
    cvt.u64.u32    %rd81, %r19;              // KD
    mul.lo.u64     %rd40, %rd40, %rd81;
    cvt.u64.u32    %rd82, %r90;              // kd
    add.s64        %rd40, %rd40, %rd82;
    cvt.u64.u32    %rd83, %r20;              // KH
    mul.lo.u64     %rd40, %rd40, %rd83;
    cvt.u64.u32    %rd84, %r96;              // kh
    add.s64        %rd40, %rd40, %rd84;
    cvt.u64.u32    %rd85, %r21;              // KW
    mul.lo.u64     %rd40, %rd40, %rd85;
    cvt.u64.u32    %rd86, %r102;             // kw
    add.s64        %rd40, %rd40, %rd86;
    shl.b64        %rd41, %rd40, 2;          // * sizeof(float)
    add.s64        %rd42, %rd11, %rd41;      // w_ptr + offset

    // Load values and accumulate
    ld.global.f32  %f1, [%rd33];
    ld.global.f32  %f2, [%rd42];
    fma.rn.f32     %f0, %f1, %f2, %f0;

    // ic++
    add.u32        %r110, %r110, 1;
    bra            IC_LOOP;
IC_END:

    // kw++
KW_CONT:
    add.u32        %r102, %r102, 1;
    bra            KW_LOOP;
KW_END:

    // kh++
KH_CONT:
    add.u32        %r96, %r96, 1;
    bra            KH_LOOP;
KH_END:

    // kd++
KD_CONT:
    add.u32        %r90, %r90, 1;
    bra            KD_LOOP;
KD_END:

    // Store result to output:
    // idx_out = (((((b*Cout + oc)*Dout + od)*Hout + oh)*Wout + ow))
    mul.wide.u32   %rd50, %r55, %r12;         // b*Cout
    cvt.u64.u32    %rd90, %r54;               // oc
    add.s64        %rd50, %rd50, %rd90;
    cvt.u64.u32    %rd91, %r16;               // Dout
    mul.lo.u64     %rd50, %rd50, %rd91;
    cvt.u64.u32    %rd92, %r53;               // od
    add.s64        %rd50, %rd50, %rd92;
    cvt.u64.u32    %rd93, %r17;               // Hout
    mul.lo.u64     %rd50, %rd50, %rd93;
    cvt.u64.u32    %rd94, %r51;               // oh
    add.s64        %rd50, %rd50, %rd94;
    cvt.u64.u32    %rd95, %r18;               // Wout
    mul.lo.u64     %rd50, %rd50, %rd95;
    cvt.u64.u32    %rd96, %r50;               // ow
    add.s64        %rd50, %rd50, %rd96;
    shl.b64        %rd51, %rd50, 2;
    add.s64        %rd52, %rd13, %rd51;
    st.global.f32  [%rd52], %f0;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans3d_kernel")

def _triple(v):
    if isinstance(v, (list, tuple)):
        assert len(v) == 3
        return tuple(int(x) for x in v)
    v = int(v)
    return (v, v, v)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        kd, kh, kw = _triple(kernel_size)
        sd, sh, sw = _triple(stride)
        pd, ph, pw = _triple(padding)
        opd, oph, opw = _triple(output_padding)
        dd, dh, dw = _triple(dilation)
        assert in_channels % groups == 0
        assert out_channels % groups == 0
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (kd, kh, kw)
        self.stride = (sd, sh, sw)
        self.padding = (pd, ph, pw)
        self.output_padding = (opd, oph, opw)
        self.dilation = (dd, dh, dw)
        self.groups = int(groups)
        self.bias_flag = bool(bias)

        # Weight layout matches PyTorch ConvTranspose3d: [in_channels, out_channels // groups, kD, kH, kW]
        self.weight = nn.Parameter(torch.empty(self.in_channels, self.out_channels // self.groups, kd, kh, kw))
        if self.bias_flag:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        # Initialize like PyTorch ConvTranspose3d (kaiming_uniform)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5.0))
        if self.bias_flag:
            fan_in = (self.weight.size(1) * kd * kh * kw)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_cuda, "Input must be on CUDA device"

        N, Cin, Din, Hin, Win = x.shape
        kd, kh, kw = self.kernel_size
        sd, sh, sw = self.stride
        pd, ph, pw = self.padding
        opd, oph, opw = self.output_padding
        dd, dh, dw = self.dilation
        G = self.groups
        Cout = self.out_channels
        assert Cin == self.in_channels
        assert self.weight.shape == (Cin, Cout // G, kd, kh, kw)

        Dout = (Din - 1) * sd - 2 * pd + dd * (kd - 1) + opd + 1
        Hout = (Hin - 1) * sh - 2 * ph + dh * (kh - 1) + oph + 1
        Wout = (Win - 1) * sw - 2 * pw + dw * (kw - 1) + opw + 1

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        func = module.function("convtrans3d_kernel")

        block_x = 16
        block_y = 4
        block_z = 1
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = (Hout + block_y - 1) // block_y
        grid_z = N * Cout * Dout

        b_ptr = self.bias if self.bias is not None else None
        b_arg = b_ptr if b_ptr is not None else u64(0)

        module.launch(
            "convtrans3d_kernel",
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(int(block_x), int(block_y), int(block_z)),
            arguments=[
                x,                      # in_ptr
                self.weight,            # w_ptr
                b_arg,                  # b_ptr (u64(0) if None)
                y,                      # out_ptr
                u32(N),
                u32(Cin),
                u32(Cout),
                u32(Din),
                u32(Hin),
                u32(Win),
                u32(Dout),
                u32(Hout),
                u32(Wout),
                u32(kd),
                u32(kh),
                u32(kw),
                u32(sd),
                u32(sh),
                u32(sw),
                u32(pd),
                u32(ph),
                u32(pw),
                u32(dd),
                u32(dh),
                u32(dw),
                u32(G),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

