    mov.u32       %r71, %r23;
    mov.u32       %r72, %r24;
    mov.u32       %r73, %r25;
    mov.u32       %r74, %r26;
    mov.u32       %r75, %r27;
    mov.u32       %r76, %r28;
    mov.u32       %r77, %r29;
    mov.u32       %r78, %r30;

    // Cast coordinates to signed
    mov.u32       %r79, %r53;  // od
    mov.u32       %r80, %r51;  // oh
    mov.u32       %r81, %r50;  // ow

