    add.s64        %rd40, %rd40, %r64;       // + oc_in_group
    mul.wide.u32   %rd40, %rd40, %r19;       // * KD
    add.s64        %rd40, %rd40, %r90;       // + kd
    mul.wide.u32   %rd40, %rd40, %r20;       // * KH
    add.s64        %rd40, %rd40, %r96;       // + kh
    mul.wide.u32   %rd40, %rd40, %r21;       // * KW
    add.s64        %rd40, %rd40, %r102;      // + kw
    mul.wide.u32   %rd41, %rd40, 4;          // * sizeof(float)
    add.s64        %rd42, %rd11, %rd41;      // w_ptr + offset

