    // kw++
KW_CONT:
    add.u32        %r102, %r102, 1;
    bra            KW_LOOP;
KW_END:

    // kh++
KH_CONT:
    add.u32        %r96, %r96, 1;
    bra            KH_LOOP;
KH_END:

    // kd++
KD_CONT:
    add.u32        %r90, %r90, 1;
    bra            KD_LOOP;
