    mul.wide.u32   %rd50, %rd50, %r16;    // * Dout
    add.s64        %rd50, %rd50, %r53;    // + od
    mul.wide.u32   %rd50, %rd50, %r17;    // * Hout
    add.s64        %rd50, %rd50, %r51;    // + oh
    mul.wide.u32   %rd50, %rd50, %r18;    // * Wout
    add.s64        %rd50, %rd50, %r50;    // + ow
    mul.wide.u32   %rd51, %rd50, 4;       // * sizeof(float)
    add.s64        %rd52, %rd13, %rd51;   // out_ptr + offset
    st.global.f32  %f0, [%rd52];

