_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans3d_kernel")

def _triple(v):
    if isinstance(v, (list, tuple)):
        assert len(v) == 3
        return tuple(int(x) for x in v)
    v = int(v)
    return (v, v, v)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        kd, kh, kw = _triple(kernel_size)
        sd, sh, sw = _triple(stride)
        pd, ph, pw = _triple(padding)
        opd, oph, opw = _triple(output_padding)
        dd, dh, dw = _triple(dilation)
        assert in_channels % groups == 0
        assert out_channels % groups == 0
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (kd, kh, kw)
        self.stride = (sd, sh, sw)
        self.padding = (pd, ph, pw)
        self.output_padding = (opd, oph, opw)
        self.dilation = (dd, dh, dw)
        self.groups = int(groups)
        self.bias_flag = bool(bias)

        # Weight layout matches PyTorch ConvTranspose3d: [in_channels, out_channels // groups, kD, kH, kW]
        self.weight = nn.Parameter(torch.empty(self.in_channels, self.out_channels // self.groups, kd, kh, kw))
        if self.bias_flag:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        # Initialize like PyTorch ConvTranspose3d (kaiming_uniform)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5.0))
        if self.bias_flag:
            fan_in = (self.weight.size(1) * kd * kh * kw)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_cuda, "Input must be on CUDA device"

        N, Cin, Din, Hin, Win = x.shape
        kd, kh, kw = self.kernel_size
        sd, sh, sw = self.stride
        pd, ph, pw = self.padding
        opd, oph, opw = self.output_padding
        dd, dh, dw = self.dilation
        G = self.groups
        Cout = self.out_channels
        assert Cin == self.in_channels
        assert self.weight.shape == (Cin, Cout // G, kd, kh, kw)

        Dout = (Din - 1) * sd - 2 * pd + dd * (kd - 1) + opd + 1
        Hout = (Hin - 1) * sh - 2 * ph + dh * (kh - 1) + oph + 1
        Wout = (Win - 1) * sw - 2 * pw + dw * (kw - 1) + opw + 1

        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        func = module.function("convtrans3d_kernel")

        block_x = 16
        block_y = 4
        block_z = 1
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = (Hout + block_y - 1) // block_y
        grid_z = N * Cout * Dout

        b_ptr = self.bias if self.bias is not None else None
        b_arg = b_ptr if b_ptr is not None else u64(0)

        module.launch(
            "convtrans3d_kernel",
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(int(block_x), int(block_y), int(block_z)),
            arguments=[
                x,                      # in_ptr
                self.weight,            # w_ptr
                b_arg,                  # b_ptr (u64(0) if None)
                y,                      # out_ptr
                u32(N),
                u32(Cin),
                u32(Cout),
                u32(Din),
                u32(Hin),
                u32(Win),
                u32(Dout),
                u32(Hout),
                u32(Wout),
                u32(kd),
                u32(kh),
                u32(kw),
                u32(sd),
                u32(sh),
                u32(sw),
                u32(pd),
                u32(ph),
                u32(pw),
                u32(dd),
                u32(dh),
                u32(dw),
                u32(G),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

